from model.autograd import Tensor
def entrainer(w,n,lr):
    w=Tensor(float(w))
    for _ in range(n):
        w.zero_grad(); loss=(w-3)*(w-3); loss.backward(); w.data-=lr*w.grad
    return float(w.data)

def budgets(e,k,poids_expert):
    if not 1<=k<=e:raise ValueError("k")
    return e*poids_expert,k*poids_expert

